/**
 * TVG Email Pass 1 — worker-only Hostinger message fetch.
 * GET metadata, text, and source. No other method. No other path.
 * Default base URL is disabled. The live host stays off until an explicit flag.
 * No token is stored here.
 */

const HOSTINGER_LIVE_HOST = 'api.mail.hostinger.com';
const DISABLED_BASE_URL = 'disabled';
const STUCK_REAL_UID = '924150001';
const DEFAULT_TIMEOUT_MS = 8000;
const DEFAULT_MAX_BODY_BYTES = 262144;

const MOCK_CASES = Object.freeze({
  910001: 'happy',
  910404: 'not_found',
  910500: 'upstream',
  910408: 'timeout',
  910601: 'missing_auth_results',
  910602: 'missing_message_id_and_date',
  910603: 'oversized',
});

const MESSAGE_PATH = /^\/api\/v1\/mailboxes\/([A-Za-z0-9_-]{1,128})\/folders\/([A-Za-z0-9._-]{1,128})\/messages\/(\d{1,18})(\/text|\/source)?$/;

function requireUuid(value) {
  const text = String(value || '');
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(text)) {
    throw new Error('expected uuid');
  }
  return text.toLowerCase();
}

function settingsArray(settings, key) {
  const value = settings?.[key];
  return Array.isArray(value) ? value : [];
}

function settingsString(settings, key, fallback) {
  const value = settings?.[key];
  if (typeof value !== 'string' || value.trim() === '') return fallback;
  return value.trim();
}

function settingsInt(settings, key, fallback, cap) {
  const n = Number(settings?.[key]);
  if (!Number.isFinite(n) || n <= 0) return fallback;
  return Math.min(Math.floor(n), cap);
}

function utf8Bytes(value) {
  const text = typeof value === 'string' ? value : JSON.stringify(value ?? '');
  let bytes = 0;
  for (let i = 0; i < text.length; i += 1) {
    const code = text.charCodeAt(i);
    if (code < 0x80) bytes += 1;
    else if (code < 0x800) bytes += 2;
    else if (code >= 0xd800 && code <= 0xdbff) {
      bytes += 4;
      i += 1;
    } else bytes += 3;
  }
  return bytes;
}

const MAILBOX_ID_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const FOLDER_PATTERN = /^[A-Za-z0-9._-]{1,128}$/;
const UID_PATTERN = /^\d{1,18}$/;

function segmentTextOk(value, pattern) {
  const text = String(value ?? '');
  if (!pattern.test(text)) return false;
  if (text === '.' || text === '..' || text.includes('..')) return false;
  if (/[/?#%@:\\]/.test(text)) return false;
  return true;
}

function encodePathSegment(value, pattern) {
  const text = String(value ?? '');
  if (!segmentTextOk(text, pattern)) throw new TypeError('path segment rejected');
  return encodeURIComponent(text);
}

function invalidUrl() {
  return new TypeError('Invalid URL');
}

function parseHttpUrl(input) {
  const raw = String(input ?? '').trim();
  const match = /^(https?):\/\/([^/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/i.exec(raw);
  if (!match) throw invalidUrl();
  const protocol = `${match[1].toLowerCase()}:`;
  let authority = match[2];
  if (!authority) throw invalidUrl();
  let username = '';
  let pass = '';
  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    const userinfo = authority.slice(0, at);
    authority = authority.slice(at + 1);
    const colon = userinfo.indexOf(':');
    if (colon === -1) username = userinfo;
    else {
      username = userinfo.slice(0, colon);
      pass = userinfo.slice(colon + 1);
    }
  }
  if (!authority || /[\s@]/.test(authority) || authority.startsWith('[')) throw invalidUrl();
  let hostname = authority;
  let port = '';
  const colon = hostname.lastIndexOf(':');
  if (colon !== -1) {
    port = hostname.slice(colon + 1);
    hostname = hostname.slice(0, colon);
    if (!/^\d{1,5}$/.test(port) || Number(port) > 65535) throw invalidUrl();
  }
  hostname = hostname.toLowerCase();
  if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/.test(hostname) && hostname !== 'localhost') {
    throw invalidUrl();
  }
  let pathname = match[3] || '/';
  if (!pathname.startsWith('/')) pathname = `/${pathname}`;
  const defaultPort = protocol === 'https:' ? '443' : '80';
  const portSuffix = port && port !== defaultPort ? `:${port}` : '';
  return {
    protocol,
    username,
    pass,
    hostname,
    port,
    pathname,
    search: match[4] || '',
    hash: match[5] || '',
    origin: `${protocol}//${hostname}${portSuffix}`,
  };
}

function composeHttpUrl(parts) {
  const defaultPort = parts.protocol === 'https:' ? '443' : '80';
  const portSuffix = parts.port && parts.port !== defaultPort ? `:${parts.port}` : '';
  const userinfo = parts.username
    ? `${parts.username}${parts.pass ? `:${parts.pass}` : ''}@`
    : (parts.pass ? `:${parts.pass}@` : '');
  let pathname = parts.pathname || '/';
  if (!pathname.startsWith('/')) pathname = `/${pathname}`;
  return `${parts.protocol}//${userinfo}${parts.hostname}${portSuffix}${pathname}`;
}

function urlBuildFailureDetail(error) {
  const name = String(error && error.name ? error.name : 'Error').replace(/[^A-Za-z0-9_]/g, '').slice(0, 40) || 'Error';
  const message = String(error && error.message ? error.message : 'url_build_failed')
    .replace(/https?:\/\/\S+/gi, '[url]')
    .replace(/bearer\s+\S+/gi, '[redacted]')
    .replace(/[\r\n\t]+/g, ' ')
    .slice(0, 160);
  return `url_build_failed:${name}:${message}`.slice(0, 220);
}

function assertHostingerGetRequest({
  method,
  url,
  baseUrl,
  allowedHosts,
  liveFetchEnabled,
}) {
  if (String(method || '').toUpperCase() !== 'GET') {
    return { ok: false, reason: 'method_rejected' };
  }
  let parsed;
  let base;
  try {
    parsed = parseHttpUrl(url);
    base = parseHttpUrl(baseUrl);
  } catch {
    return { ok: false, reason: 'url_rejected' };
  }
  if (parsed.protocol !== 'https:') return { ok: false, reason: 'scheme_rejected' };
  const userinfo = parsed.username || parsed.pass;
  if (userinfo) return { ok: false, reason: 'url_rejected' };
  if (parsed.origin !== base.origin) return { ok: false, reason: 'host_rejected' };
  if (parsed.search || parsed.hash) return { ok: false, reason: 'query_rejected' };
  const basePath = base.pathname.replace(/\/+$/, '');
  if (!parsed.pathname.startsWith(`${basePath}/`)) return { ok: false, reason: 'path_rejected' };
  let relative;
  try {
    relative = decodeURIComponent(parsed.pathname.slice(basePath.length));
  } catch {
    return { ok: false, reason: 'path_rejected' };
  }
  if (relative.includes('..') || !MESSAGE_PATH.test(relative)) {
    return { ok: false, reason: 'path_rejected' };
  }
  const host = parsed.hostname.toLowerCase();
  const allowed = (allowedHosts || []).map((item) => String(item).trim().toLowerCase()).filter(Boolean);
  if (!allowed.includes(host)) return { ok: false, reason: 'host_rejected' };
  if (host === HOSTINGER_LIVE_HOST && liveFetchEnabled !== true) {
    return { ok: false, reason: 'live_fetch_disabled' };
  }
  return { ok: true, host, path: relative };
}

function buildMessageUrl(baseUrl, pointer, suffix) {
  if (suffix !== '' && suffix !== 'text' && suffix !== 'source') {
    throw new TypeError('suffix rejected');
  }
  const base = parseHttpUrl(baseUrl);
  const id = encodePathSegment(pointer.mailbox_resource_id, MAILBOX_ID_PATTERN);
  const folder = encodePathSegment(pointer.folder, FOLDER_PATTERN);
  const uid = encodePathSegment(String(pointer.uid), UID_PATTERN);
  const tail = suffix ? `/${suffix}` : '';
  const prefix = base.pathname.replace(/\/+$/, '');
  const pathname = `${prefix}/api/v1/mailboxes/${id}/folders/${folder}/messages/${uid}${tail}`;
  const relative = pathname.slice(prefix.length);
  if (relative.includes('..') || !MESSAGE_PATH.test(relative)) {
    throw new TypeError('path segment rejected');
  }
  return composeHttpUrl({
    protocol: base.protocol,
    username: base.username,
    pass: base.pass,
    hostname: base.hostname,
    port: base.port,
    pathname,
  });
}

function resolveStoredPointer(queue) {
  const column = {
    mailbox_resource_id: queue.mailbox_resource_id,
    folder: queue.folder,
    uid: queue.uid == null ? '' : String(queue.uid),
    mailbox: queue.mailbox,
  };
  const pointers = queue.hostinger_pointers && typeof queue.hostinger_pointers === 'object'
    ? queue.hostinger_pointers
    : {};
  const mirrored = [
    ['mailbox_resource_id', pointers.mailbox_resource_id],
    ['folder', pointers.folder],
    ['uid', pointers.uid == null || pointers.uid === '' ? undefined : String(pointers.uid)],
  ];
  for (const [key, value] of mirrored) {
    if (value != null && value !== '' && String(value) !== String(column[key] ?? '')) {
      return { ok: false, detail: `pointer_mismatch:${key}` };
    }
  }
  if (!segmentTextOk(column.mailbox_resource_id, MAILBOX_ID_PATTERN)) {
    return { ok: false, detail: 'mailbox_resource_id_unresolved' };
  }
  if (!segmentTextOk(column.folder, FOLDER_PATTERN)) {
    return { ok: false, detail: 'folder_unresolved' };
  }
  if (!segmentTextOk(column.uid, UID_PATTERN)) return { ok: false, detail: 'uid_unresolved' };
  if (!/^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(String(column.mailbox || ''))) {
    return { ok: false, detail: 'mailbox_unresolved' };
  }
  return {
    ok: true,
    mailbox_resource_id: String(column.mailbox_resource_id),
    folder: String(column.folder),
    uid: column.uid,
    mailbox: String(column.mailbox).toLowerCase(),
  };
}

function holdPlan(common, fields) {
  return {
    ...common,
    route: 'hold',
    metadata_url: null,
    text_url: null,
    source_url: null,
    ...fields,
  };
}

function planWorkerRoute({
  queueRow,
  settings = {},
  filterRows = [],
  formSenders = [],
  contacts = [],
  leads = [],
}) {
  const baseUrl = settingsString(settings, 'hostinger_mail_api_base_url', DISABLED_BASE_URL);
  const timeoutMs = settingsInt(settings, 'hostinger_fetch_timeout_ms', DEFAULT_TIMEOUT_MS, 20000);
  const maxBodyBytes = settingsInt(settings, 'hostinger_fetch_max_body_bytes', DEFAULT_MAX_BODY_BYTES, 1048576);
  const common = {
    queue_row: queueRow || null,
    filter_rows: filterRows || [],
    form_senders: formSenders || [],
    settings,
    contacts: contacts || [],
    leads: leads || [],
    fetch_base_url: baseUrl,
    timeout_ms: timeoutMs,
    max_body_bytes: maxBodyBytes,
    metadata_url: null,
    text_url: null,
    source_url: null,
    hold_reason: null,
    error_code: null,
    queue_status: null,
    detail: null,
  };
  if (!queueRow) return { ...common, route: 'skip' };
  const pointers = queueRow.hostinger_pointers || {};
  if (pointers.synthetic_message) return { ...common, route: 'synthetic' };
  const excluded = new Set([
    STUCK_REAL_UID,
    ...settingsArray(settings, 'hostinger_fetch_excluded_uids').map((value) => String(value)),
  ]);
  if (excluded.has(String(queueRow.uid))) {
    return holdPlan(common, {
      fetch_base_url: 'excluded',
      hold_reason: 'excluded_stuck_uid',
      error_code: 'excluded_stuck_uid',
      queue_status: 'held',
      detail: 'non-synthetic uid 924150001 is excluded from fetch',
    });
  }
  const pointer = resolveStoredPointer(queueRow);
  if (!pointer.ok) {
    return holdPlan(common, {
      hold_reason: 'pointer_unresolved',
      error_code: 'pointer_unresolved',
      queue_status: 'held',
      detail: pointer.detail,
    });
  }
  if (baseUrl === DISABLED_BASE_URL || baseUrl === 'off' || baseUrl === 'mock') {
    return holdPlan(common, {
      hold_reason: 'hostinger_fetch_disabled',
      error_code: 'hostinger_fetch_disabled',
      queue_status: 'held',
      detail: 'base URL is disabled; no request was made',
    });
  }
  let urls;
  try {
    urls = {
      metadata: buildMessageUrl(baseUrl, pointer, ''),
      text: buildMessageUrl(baseUrl, pointer, 'text'),
      source: buildMessageUrl(baseUrl, pointer, 'source'),
    };
  } catch (error) {
    return holdPlan(common, {
      hold_reason: 'pointer_unresolved',
      error_code: 'pointer_unresolved',
      queue_status: 'held',
      detail: urlBuildFailureDetail(error),
    });
  }
  const allowedHosts = settingsArray(settings, 'hostinger_mail_api_allowed_hosts');
  const liveFetchEnabled = settings.hostinger_live_fetch_enabled === true;
  for (const [name, url] of Object.entries(urls)) {
    const guard = assertHostingerGetRequest({
      method: 'GET',
      url,
      baseUrl,
      allowedHosts,
      liveFetchEnabled,
    });
    if (!guard.ok) {
      const reason = guard.reason === 'live_fetch_disabled'
        ? 'hostinger_live_fetch_disabled'
        : 'hostinger_request_rejected';
      return holdPlan(common, {
        hold_reason: reason,
        error_code: guard.reason,
        queue_status: 'held',
        detail: `${name}:${guard.reason}`,
      });
    }
  }
  return {
    ...common,
    route: 'fetch',
    metadata_url: urls.metadata,
    text_url: urls.text,
    source_url: urls.source,
  };
}

function buildClosedHoldSql(input) {
  const queueId = requireUuid(input.queue_id);
  const queueStatus = input.queue_status === 'error' ? 'error' : 'held';
  const holdReason = String(input.hold_reason || 'pointer_unresolved').slice(0, 80);
  const errorCode = String(input.error_code || holdReason).slice(0, 80);
  const detail = String(input.detail || holdReason).slice(0, 400);
  const fetchBaseUrl = String(input.fetch_base_url || DISABLED_BASE_URL).slice(0, 300);
  const sql = `
WITH closed AS (
  UPDATE email_automation.intake_queue q
  SET status = ${quoteLiteral(queueStatus)}::email_automation.intake_queue_status,
      hold_reason = ${quoteLiteral(holdReason)},
      last_error = ${quoteLiteral(detail)},
      hostinger_pointers = COALESCE(q.hostinger_pointers, '{}'::jsonb) || jsonb_build_object(
        'fetch_base_url', ${quoteLiteral(fetchBaseUrl)}::text,
        'fetch_mode', 'closed'::text,
        'fetch_error_code', ${quoteLiteral(errorCode)}::text
      )
  WHERE q.id = ${quoteLiteral(queueId)}::uuid
    AND q.tenant_id = 'tvg'
  RETURNING q.id
)
INSERT INTO email_automation.automation_errors (
  tenant_id, intake_queue_id, stage, error_code, error_message, context_json, retryable
)
SELECT
  'tvg',
  closed.id,
  'worker_fetch',
  ${quoteLiteral(errorCode)},
  ${quoteLiteral(detail)},
  jsonb_build_object('fetch_base_url', ${quoteLiteral(fetchBaseUrl)}::text),
  FALSE
FROM closed
RETURNING intake_queue_id AS id,
  ${quoteLiteral(queueStatus)}::text AS status,
  NULL::uuid AS email_event_id,
  FALSE AS was_existing,
  NULL::timestamptz AS event_created_at;
`.trim();
  if (/email_responses|email_send_queue|developers\.hostinger|insert\s+into\s+public\./i.test(sql)) {
    throw new Error('refusing closed-hold SQL');
  }
  return sql;
}

function recheckFetchPlan(plan) {
  if (!plan || plan.route !== 'fetch') return { ok: false, detail: 'not_fetch' };
  const allowedHosts = settingsArray(plan.settings, 'hostinger_mail_api_allowed_hosts');
  const liveFetchEnabled = plan.settings?.hostinger_live_fetch_enabled === true;
  const requests = [
    { method: 'GET', url: plan.metadata_url },
    { method: 'GET', url: plan.text_url },
    { method: 'GET', url: plan.source_url },
  ];
  for (const request of requests) {
    const guard = assertHostingerGetRequest({
      method: request.method,
      url: request.url,
      baseUrl: plan.fetch_base_url,
      allowedHosts,
      liveFetchEnabled,
    });
    if (!guard.ok) {
      return {
        ok: false,
        fetch_base_url: plan.fetch_base_url,
        hold_reason: 'hostinger_request_rejected',
        sql: buildClosedHoldSql({
          queue_id: plan.queue_row.id,
          queue_status: 'held',
          hold_reason: 'hostinger_request_rejected',
          error_code: guard.reason,
          detail: guard.reason,
          fetch_base_url: plan.fetch_base_url,
        }),
      };
    }
  }
  return { ok: true };
}

function responsePayload(item) {
  if (item == null || typeof item !== 'object' || Array.isArray(item)) return item;
  if (Object.prototype.hasOwnProperty.call(item, 'body')) return item.body;
  if (Object.prototype.hasOwnProperty.call(item, 'data')) return item.data;
  return item;
}

function parseJsonEnvelope(raw) {
  if (typeof raw !== 'string') return { ok: false, reason: 'non_object' };
  const trimmed = raw.trim();
  if (trimmed === '') return { ok: false, reason: 'empty' };
  if (trimmed === 'null') return { ok: false, reason: 'null' };
  let parsed;
  try {
    parsed = JSON.parse(trimmed);
  } catch {
    return { ok: false, reason: 'invalid_json' };
  }
  if (parsed === null) return { ok: false, reason: 'null' };
  if (typeof parsed !== 'object' || Array.isArray(parsed)) return { ok: false, reason: 'non_object' };
  const inner = parsed.data;
  if (inner == null || typeof inner !== 'object' || Array.isArray(inner)) {
    return { ok: false, reason: 'missing_envelope' };
  }
  return { ok: true, value: inner };
}

function sourceRawString(raw) {
  if (typeof raw === 'string') {
    const trimmed = raw.trim();
    if (trimmed.startsWith('{')) {
      try {
        const parsed = JSON.parse(trimmed);
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && typeof parsed.data === 'string') {
          return parsed.data;
        }
      } catch {
        /* rfc822 that is not an envelope stays the original string */
      }
    }
    return raw;
  }
  if (raw && typeof raw === 'object' && typeof raw.data === 'string') return raw.data;
  return '';
}

function unwrapHttp(item, endpoint) {
  if (item == null) return { status: 0, body: null, timedOut: true, error: 'empty', parseError: null };
  if (typeof item !== 'object') {
    return { status: 200, body: item, timedOut: false, error: null, parseError: null };
  }
  if (item.error) {
    const message = String(item.error.message || item.error.description || item.error);
    const timedOut = /timeout|timed out|etimedout|econnaborted|aborted/i.test(message);
    return {
      status: Number(item.error.status || item.error.httpCode || 0),
      body: null,
      timedOut,
      error: message.slice(0, 300),
      parseError: null,
    };
  }
  const status = Number(item.statusCode || item.status || 0) || 200;
  const raw = responsePayload(item);
  if (endpoint === 'source') {
    return { status, body: sourceRawString(raw), timedOut: false, error: null, parseError: null };
  }
  if (status < 200 || status >= 300) {
    return { status, body: raw, timedOut: false, error: null, parseError: null };
  }
  const parsed = parseJsonEnvelope(raw);
  if (!parsed.ok) {
    return { status, body: null, timedOut: false, error: null, parseError: parsed.reason };
  }
  return { status, body: parsed.value, timedOut: false, error: null, parseError: null };
}

function parseHold(endpoint, reason) {
  return {
    queue_status: 'held',
    hold_reason: 'parse_failed',
    error_code: `parse_failed:${endpoint}`,
    detail: String(reason || 'parse_failed'),
  };
}

function parseRfc822(raw) {
  const text = String(raw || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const splitAt = text.indexOf('\n\n');
  const headerBlock = splitAt === -1 ? text : text.slice(0, splitAt);
  const body = splitAt === -1 ? '' : text.slice(splitAt + 2);
  const unfolded = headerBlock.replace(/\n[ \t]+/g, ' ');
  const headers = {};
  for (const line of unfolded.split('\n')) {
    const idx = line.indexOf(':');
    if (idx <= 0) continue;
    const name = line.slice(0, idx).trim().toLowerCase();
    const value = line.slice(idx + 1).trim();
    if (!name) continue;
    headers[name] = headers[name] ? `${headers[name]}\n${value}` : value;
  }
  return { headers, body };
}

function sourceText(body) {
  if (typeof body === 'string') return body;
  if (!body || typeof body !== 'object') return '';
  if (typeof body.source === 'string') return body.source;
  if (typeof body.data === 'string') return body.data;
  return '';
}

function metadataObject(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return {};
  const data = body.data && typeof body.data === 'object' && !Array.isArray(body.data) ? body.data : body;
  return data;
}

function textParts(body) {
  const data = metadataObject(body);
  return {
    text: data.text == null ? '' : String(data.text),
    html: data.html == null ? '' : String(data.html),
  };
}

function addressText(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'object' && value.address) {
    const name = value.name ? String(value.name).replace(/[<>]/g, '') : '';
    return name ? `${name} <${value.address}>` : String(value.address);
  }
  return '';
}

function addressList(value) {
  if (!Array.isArray(value)) return '';
  return value.map(addressText).filter(Boolean).join(', ');
}

function bareId(value) {
  return String(value || '').trim().replace(/^<|>$/g, '').toLowerCase();
}

function loose(value) {
  return String(value || '').replace(/\s+/g, ' ').trim().toLowerCase();
}

function attachmentMeta(list) {
  if (!Array.isArray(list)) return [];
  return list.map((item) => ({
    filename: item?.filename ?? null,
    content_type: item?.contentType || item?.content_type || null,
    size_bytes: item?.sizeBytes ?? item?.size_bytes ?? null,
    attachment_id: item?.id || item?.attachment_id || null,
  }));
}

function retrievalFailure(meta, text, source) {
  const parts = [meta, text, source];
  if (parts.some((part) => part.timedOut)) {
    return { queue_status: 'error', hold_reason: 'hostinger_timeout', error_code: 'hostinger_timeout', detail: 'timeout' };
  }
  if (parts.some((part) => part.status >= 500)) {
    return { queue_status: 'error', hold_reason: 'hostinger_upstream_error', error_code: 'hostinger_upstream_error', detail: 'upstream' };
  }
  if (parts.some((part) => part.status === 404)) {
    return {
      queue_status: 'held',
      hold_reason: 'message_moved_uncertain',
      error_code: 'hostinger_not_found',
      detail: 'not_found_no_search',
    };
  }
  if (parts.some((part) => part.status === 401 || part.status === 403)) {
    return { queue_status: 'error', hold_reason: 'hostinger_auth_rejected', error_code: 'hostinger_auth_rejected', detail: 'auth' };
  }
  if (parts.some((part) => part.status < 200 || part.status >= 300)) {
    return { queue_status: 'held', hold_reason: 'hostinger_client_error', error_code: 'hostinger_client_error', detail: 'client_status' };
  }
  return null;
}

function normalizeHostingerPayload({
  metadataBody,
  textBody,
  sourceBody,
  mailbox,
  maxBodyBytes,
}) {
  const rawSizes = [metadataBody, textBody, sourceBody].map(utf8Bytes);
  if (rawSizes.some((size) => size > maxBodyBytes)) {
    return { ok: false, code: 'hostinger_body_too_large', detail: 'body_too_large' };
  }
  const sourceRaw = sourceText(sourceBody);
  if (!sourceRaw.trim()) {
    return { ok: false, code: 'identity_uncertain', detail: 'missing_source', uncertain: true };
  }
  const parsed = parseRfc822(sourceRaw);
  const auth = parsed.headers['authentication-results'] || '';
  if (!String(auth).trim()) {
    return {
      ok: false,
      code: 'identity_uncertain',
      detail: 'missing_authentication_results',
      uncertain: true,
      partial: assembleMessage({ parsed, metadataBody, textBody, mailbox, auth: '' }),
    };
  }
  const message = assembleMessage({ parsed, metadataBody, textBody, mailbox, auth });
  if (message.conflict) {
    return { ok: false, code: 'identity_uncertain', detail: message.conflict, uncertain: true, partial: message };
  }
  return { ok: true, message };
}

function assembleMessage({ parsed, metadataBody, textBody, mailbox, auth }) {
  const meta = metadataObject(metadataBody);
  const parts = textParts(textBody);
  const headerFrom = parsed.headers.from || '';
  const metaFrom = addressText(meta.from);
  const headerId = parsed.headers['message-id'] || '';
  const metaId = meta.messageId || meta.message_id || '';
  const headerSubject = parsed.headers.subject || '';
  const metaSubject = meta.subject == null ? '' : String(meta.subject);
  let conflict = '';
  if (headerFrom && metaFrom && normalizeEmail(headerFrom) && normalizeEmail(metaFrom)
    && normalizeEmail(headerFrom) !== normalizeEmail(metaFrom)) {
    conflict = 'from_mismatch';
  }
  if (headerId && metaId && bareId(headerId) !== bareId(metaId)) conflict = conflict || 'message_id_mismatch';
  if (headerSubject && metaSubject && loose(headerSubject) !== loose(metaSubject)) conflict = conflict || 'subject_mismatch';
  const contentType = String(parsed.headers['content-type'] || '');
  let bodyText = parts.text;
  if (!bodyText && !parts.html && (contentType === '' || /^text\/plain/i.test(contentType))) {
    bodyText = parsed.body;
  }
  return {
    conflict,
    mailbox,
    from_raw: headerFrom || metaFrom,
    from_name: meta.from && typeof meta.from === 'object' ? (meta.from.name || '') : '',
    reply_to_raw: parsed.headers['reply-to'] || '',
    to_raw: parsed.headers.to || addressList(meta.to),
    cc_raw: parsed.headers.cc || addressList(meta.cc),
    subject: headerSubject || metaSubject,
    date_header: parsed.headers.date || '',
    bodyText,
    bodyHtml: parts.html,
    message_id: headerId || metaId || '',
    authentication_results: auth,
    in_reply_to: parsed.headers['in-reply-to'] || meta.inReplyTo || meta.in_reply_to || '',
    references: parsed.headers.references || '',
    auto_submitted: parsed.headers['auto-submitted'] || '',
    precedence_header: parsed.headers.precedence || '',
    list_id: parsed.headers['list-id'] || '',
    content_type: contentType,
    attachment_meta: attachmentMeta(meta.attachments),
  };
}

function displayFrom(message, decision) {
  return {
    senderName: message.from_name || '',
    senderEmail: decision.from_email || '',
    subject: message.subject || '',
    formFields: { service: '', city: '' },
  };
}

function outcomeFromDecision(decision, plan, message) {
  const sql = buildOutcomeSql({
    ...decision,
    queue_id: plan.queue_row.id,
    mailbox: plan.queue_row.mailbox,
    mailbox_resource_id: plan.queue_row.mailbox_resource_id,
    folder: plan.queue_row.folder,
    uid: String(plan.queue_row.uid),
    subject: message.subject || null,
    date_header: message.date_header || null,
    authentication_results: message.authentication_results || null,
    body_excerpt: decision.body_normalized || '',
    in_reply_to: message.in_reply_to || null,
    references: message.references || null,
    attachment_meta: message.attachment_meta || null,
    fetch_base_url: plan.fetch_base_url,
    fetch_mode: 'get',
  });
  return { sql, decision, display: displayFrom(message, decision), fetch_base_url: plan.fetch_base_url };
}

function forcedUncertain(plan, message) {
  const prepared = {
    ...message,
    from_email: normalizeEmail(message.from_raw),
    reply_to_email: normalizeEmail(message.reply_to_raw),
    to_email: normalizeEmail(message.to_raw),
    mailbox_email: normalizeEmail(message.mailbox),
  };
  const identity = computeIdentity(prepared);
  const auth = parseAuthResults(prepared.authentication_results);
  const canPersist = Boolean(identity.message_id)
    || Boolean(prepared.from_email && (prepared.bodyText || prepared.subject || prepared.date_header));
  if (!canPersist) {
    return {
      sql: buildClosedHoldSql({
        queue_id: plan.queue_row.id,
        queue_status: 'held',
        hold_reason: 'identity_uncertain',
        error_code: 'identity_uncertain',
        detail: 'identity_uncertain_no_event',
        fetch_base_url: plan.fetch_base_url,
      }),
      decision: { event_status: 'held', queue_status: 'held', hold_reason: 'identity_uncertain' },
      display: displayFrom(message, { from_email: prepared.from_email }),
      fetch_base_url: plan.fetch_base_url,
    };
  }
  return outcomeFromDecision({
    ...identity,
    from_email: prepared.from_email,
    reply_to_email: prepared.reply_to_email,
    spf_pass: auth.spf_pass,
    dkim_pass: auth.dkim_pass,
    dmarc_pass: auth.dmarc_pass,
    is_form_sender: false,
    contact_id: null,
    lead_id: null,
    resolved_recipient: null,
    recipient_resolution: null,
    hold_reason: 'identity_uncertain',
    filter_reason: null,
    event_status: 'held',
    queue_status: 'held',
  }, plan, message);
}

function decideFetchedIntake({ plan, metadataItem, textItem, sourceItem }) {
  const meta = unwrapHttp(metadataItem, 'metadata');
  const text = unwrapHttp(textItem, 'text');
  const source = unwrapHttp(sourceItem, 'source');
  const failure = retrievalFailure(meta, text, source)
    || (meta.parseError ? parseHold('metadata', meta.parseError) : null)
    || (text.parseError ? parseHold('text', text.parseError) : null);
  if (failure) {
    return {
      sql: buildClosedHoldSql({
        queue_id: plan.queue_row.id,
        queue_status: failure.queue_status,
        hold_reason: failure.hold_reason,
        error_code: failure.error_code,
        detail: failure.detail,
        fetch_base_url: plan.fetch_base_url,
      }),
      decision: {
        event_status: failure.queue_status === 'error' ? 'error' : 'held',
        queue_status: failure.queue_status,
        hold_reason: failure.hold_reason,
      },
      display: {},
      fetch_base_url: plan.fetch_base_url,
    };
  }
  const normalized = normalizeHostingerPayload({
    metadataBody: meta.body,
    textBody: text.body,
    sourceBody: source.body,
    mailbox: plan.queue_row.mailbox,
    maxBodyBytes: plan.max_body_bytes || DEFAULT_MAX_BODY_BYTES,
  });
  if (!normalized.ok && normalized.code === 'hostinger_body_too_large') {
    return {
      sql: buildClosedHoldSql({
        queue_id: plan.queue_row.id,
        queue_status: 'held',
        hold_reason: 'hostinger_body_too_large',
        error_code: 'hostinger_body_too_large',
        detail: 'body_too_large',
        fetch_base_url: plan.fetch_base_url,
      }),
      decision: { event_status: 'held', queue_status: 'held', hold_reason: 'hostinger_body_too_large' },
      display: {},
      fetch_base_url: plan.fetch_base_url,
    };
  }
  if (!normalized.ok) {
    return forcedUncertain(plan, normalized.partial || {
      mailbox: plan.queue_row.mailbox,
      from_raw: '',
      subject: '',
      date_header: '',
      bodyText: '',
      message_id: '',
      authentication_results: '',
    });
  }
  const decision = evaluateIntake({
    message: normalized.message,
    filterRows: plan.filter_rows || [],
    formSenders: plan.form_senders || [],
    settings: plan.settings || {},
    contacts: plan.contacts || [],
    leads: plan.leads || [],
  });
  return outcomeFromDecision(decision, plan, normalized.message);
}

function happySource({ uid, subject, messageId, date, auth, from }) {
  const lines = [
    messageId ? `Message-ID: ${messageId}` : null,
    date ? `Date: ${date}` : null,
    `From: ${from}`,
    'Reply-To: Pat Customer <pat@example.com>',
    'To: TVG <info@vent-guys.com>',
    `Subject: ${subject}`,
    auth ? `Authentication-Results: ${auth}` : null,
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset=utf-8',
    '',
    `Hello from mock uid ${uid}.`,
  ].filter((line) => line != null);
  return lines.join('\r\n');
}

function renderMockHostingerResponse({ uid, kind }) {
  const mode = MOCK_CASES[String(uid)] || 'not_found';
  if (mode === 'not_found') {
    return { http_status: 404, response_body: { error: 'not_found', uid: String(uid) }, timeout: false };
  }
  if (mode === 'upstream') {
    return { http_status: 500, response_body: { error: 'upstream', uid: String(uid) }, timeout: false };
  }
  if (mode === 'timeout') {
    return { http_status: 200, response_body: { error: 'delayed', uid: String(uid) }, timeout: true };
  }
  const omitAuth = mode === 'missing_auth_results';
  const omitId = mode === 'missing_message_id_and_date';
  const subject = 'Synthetic mock inquiry';
  const from = 'Pat Customer <pat@example.com>';
  const messageId = omitId ? '' : `<mock-${uid}@example.com>`;
  const date = omitId ? '' : 'Thu, 25 Sep 2026 14:00:00 +0000';
  const auth = omitAuth ? '' : 'mock.example; spf=pass smtp.mailfrom=example.com; dkim=pass header.d=example.com; dmarc=pass header.from=example.com';
  if (kind === 'metadata') {
    return {
      http_status: 200,
      timeout: false,
      response_body: {
        data: {
          uid: Number(uid),
          path: 'INBOX',
          date: date || null,
          flags: [],
          unseen: true,
          size: 400,
          subject,
          from: { name: 'Pat Customer', address: 'pat@example.com' },
          to: [{ name: 'TVG', address: 'info@vent-guys.com' }],
          cc: [],
          bcc: [],
          messageId: messageId || null,
          inReplyTo: null,
          attachments: [],
        },
      },
    };
  }
  if (kind === 'text') {
    const text = mode === 'oversized' ? 'x'.repeat(300000) : `Hello from mock uid ${uid}.`;
    return { http_status: 200, timeout: false, response_body: { data: { text, html: '' } } };
  }
  return {
    http_status: 200,
    timeout: false,
    response_body: {
      data: happySource({ uid, subject, messageId, date, auth, from }),
    },
  };
}



function refuseUnsafeSql(sql) {
  if (/email_responses|email_send_queue|developers\.hostinger|insert\s+into\s+public\./i.test(sql || '')) {
    throw new Error('refusing SQL that mentions send tables, public inserts, or the Hostinger developers host');
  }
}


function nodeJson(name) {
  try {
    const item = $(name).first();
    return item ? item.json : null;
  } catch (error) {
    return { error: { message: 'node ' + name + ' did not run' } };
  }
}
const plan = nodeJson('Plan route') || {};
const decided = decideFetchedIntake({
  plan,
  metadataItem: nodeJson('Fetch metadata'),
  textItem: nodeJson('Fetch text'),
  sourceItem: nodeJson('Fetch source'),
});
refuseUnsafeSql(decided.sql);
return [{ json: decided }];

/**
 * TVG Email Pass 1 intake decisions (staging build).
 * Design source: pass1-v5 docs 04, 06, 07, plus the challenge supplement:
 * form path is known_form_senders allowlist only, and that From is judged
 * for form_auth_failure before any email_filter_lists deny can mark it filtered.
 *
 * No send path. No email_responses. No email_send_queue.
 * Hostinger GET lives only in pass1-hostinger-fetch.mjs and only on the worker.
 */

const PSL_SUBSET_ID = 'tvg-email-pass1-psl-subset-2026-09-24';

/** Not the Mozilla public suffix list. Pre-webhook must pin a full PSL package. */
const PSL_SUBSET = Object.freeze([
  'com',
  'net',
  'org',
  'uk',
  'co.uk',
  'org.uk',
  'com.au',
  'co.nz',
  'com.br',
]);

const EVENT_STATUSES = new Set([
  'filtered',
  'system_lessen',
  'held',
  'awaiting_pass2',
  'duplicate_ignored',
  'error',
]);

const QUEUE_STATUSES = new Set(['done', 'duplicate', 'held', 'error']);

const HOLD_REASONS = new Set([
  'form_auth_failure',
  'phone_conflict',
  'reply_to_domain_mismatch',
  'ambiguous_recipient',
  'ambiguous_contact',
  'message_moved_uncertain',
  'identity_uncertain',
  'stale_processing',
  'cross_tenant_match',
]);

function rotr(x, n) {
  return (x >>> n) | (x << (32 - n));
}

function sha256HexFromBytes(bytes) {
  const K = new Uint32Array([
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ]);
  const H = new Uint32Array([
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ]);
  const bitLen = bytes.length * 8;
  const withOne = bytes.length + 1;
  const padLen = (56 - (withOne % 64) + 64) % 64;
  const total = bytes.length + 1 + padLen + 8;
  const buf = new Uint8Array(total);
  buf.set(bytes, 0);
  buf[bytes.length] = 0x80;
  const view = new DataView(buf.buffer);
  view.setUint32(total - 8, Math.floor(bitLen / 2 ** 32));
  view.setUint32(total - 4, bitLen >>> 0);
  const w = new Uint32Array(64);
  for (let i = 0; i < total; i += 64) {
    for (let t = 0; t < 16; t += 1) w[t] = view.getUint32(i + t * 4);
    for (let t = 16; t < 64; t += 1) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let a = H[0];
    let b = H[1];
    let c = H[2];
    let d = H[3];
    let e = H[4];
    let f = H[5];
    let g = H[6];
    let h = H[7];
    for (let t = 0; t < 64; t += 1) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0;
    H[1] = (H[1] + b) >>> 0;
    H[2] = (H[2] + c) >>> 0;
    H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0;
    H[5] = (H[5] + f) >>> 0;
    H[6] = (H[6] + g) >>> 0;
    H[7] = (H[7] + h) >>> 0;
  }
  return Array.from(H, (x) => x.toString(16).padStart(8, '0')).join('');
}

function sha256Hex(text) {
  return sha256HexFromBytes(new TextEncoder().encode(String(text)));
}

function quoteLiteral(value) {
  if (value === null || value === undefined) return 'NULL';
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new Error('non-finite number');
    return String(value);
  }
  if (typeof value === 'boolean') return value ? 'TRUE' : 'FALSE';
  const text = String(value);
  if (text.includes('\u0000')) throw new Error('NUL not allowed');
  return `'${text.replace(/'/g, "''")}'`;
}

function requireUuid(value) {
  const text = String(value || '');
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(text)) {
    throw new Error('expected uuid');
  }
  return text.toLowerCase();
}

function normalizeEmail(raw) {
  if (raw == null) return '';
  let text = String(raw).trim();
  const angle = text.match(/<([^<>]+)>/);
  if (angle) text = angle[1].trim();
  text = text.toLowerCase();
  if (!text || /\s/.test(text) || !text.includes('@')) return '';
  const parts = text.split('@');
  if (parts.length !== 2 || !parts[0] || !parts[1]) return '';
  return text;
}

function normalizeSubject(raw) {
  if (raw == null) return '';
  return String(raw)
    .normalize('NFC')
    .replace(/^[\s\u00a0]+|[\s\u00a0]+$/g, '')
    .replace(/[\t\n\r\f\v\u00a0 ]+/g, ' ')
    .toLowerCase();
}

function normalizeDateHeader(raw) {
  if (raw == null || String(raw).trim() === '') return '';
  return String(raw)
    .normalize('NFC')
    .replace(/^[\s\u00a0]+|[\s\u00a0]+$/g, '')
    .replace(/[\t\n\r\f\v\u00a0 ]+/g, ' ');
}

function decodeHtmlEntities(text) {
  const named = {
    '&nbsp;': ' ',
    '&amp;': '&',
    '&lt;': '<',
    '&gt;': '>',
    '&quot;': '"',
    '&apos;': "'",
    '&#39;': "'",
  };
  let out = text;
  for (const [from, to] of Object.entries(named)) out = out.split(from).join(to);
  out = out.replace(/&#x([0-9a-f]+);/gi, (_m, hex) => codePointToChar(parseInt(hex, 16)));
  out = out.replace(/&#(\d+);/g, (_m, dec) => codePointToChar(parseInt(dec, 10)));
  return out;
}

function codePointToChar(n) {
  if (!Number.isFinite(n)) return '';
  const allowed = n === 0x09 || n === 0x0a || n === 0x0d || (n >= 0x20 && n <= 0x10ffff && !(n >= 0xd800 && n <= 0xdfff));
  if (!allowed) return '';
  return String.fromCodePoint(n);
}

function htmlToTextV1(html) {
  let text = String(html ?? '').normalize('NFC');
  let prev;
  do {
    prev = text;
    text = text.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '');
    text = text.replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '');
  } while (text !== prev);
  text = text.replace(/<br\s*\/?>|<\/p>|<\/div>|<\/tr>|<\/li>|<\/h[1-6]>|<\/table>|<\/blockquote>/gi, '\n');
  text = text.replace(/<[^>]+>/g, '');
  return decodeHtmlEntities(text);
}

function normalizeBodyV1({ bodyText, bodyHtml }) {
  let source = '';
  if (bodyText != null && String(bodyText).trim() !== '') source = String(bodyText);
  else if (bodyHtml != null && String(bodyHtml).trim() !== '') source = htmlToTextV1(bodyHtml);
  let text = source.normalize('NFC').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  text = text
    .split('\n')
    .map((line) => line.replace(/[ \t\v\f\u00a0]+$/g, ''))
    .join('\n');
  text = text.replace(/\n{3,}/g, '\n\n').replace(/^\n+|\n+$/g, '');
  return text;
}

function registrableDomain(host, suffixes = PSL_SUBSET) {
  const normalized = String(host || '').trim().toLowerCase().replace(/\.$/, '');
  if (!normalized || normalized.includes(' ') || !normalized.includes('.')) return '';
  const labels = normalized.split('.');
  const set = new Set(suffixes.map((s) => s.toLowerCase()));
  let best = '';
  for (let i = 0; i < labels.length; i += 1) {
    const candidate = labels.slice(i).join('.');
    if (set.has(candidate) && candidate.length > best.length) best = candidate;
  }
  if (!best) return labels.slice(-2).join('.');
  const suffixLen = best.split('.').length;
  if (labels.length <= suffixLen) return normalized;
  return labels.slice(-(suffixLen + 1)).join('.');
}

function parseAuthResults(header) {
  const text = String(header || '');
  const grab = (name) => {
    const match = text.match(new RegExp(`\\b${name}\\s*=\\s*(pass|fail|softfail|neutral|none|temperror|permerror)\\b`, 'i'));
    return match ? match[1].toLowerCase() : '';
  };
  const spf = grab('spf');
  const dkim = grab('dkim');
  const dmarc = grab('dmarc');
  return {
    spf,
    dkim,
    dmarc,
    spf_pass: spf === 'pass',
    dkim_pass: dkim === 'pass',
    dmarc_pass: dmarc === 'pass',
    all_pass: spf === 'pass' && dkim === 'pass' && dmarc === 'pass',
  };
}

const POINTER_RULES = {
  mailbox_resource_id: /^[A-Za-z0-9_-]{1,128}$/,
  folder: /^[A-Za-z0-9._-]{1,128}$/,
  mailbox: /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/,
  event_type: /^[A-Za-z0-9._:-]{1,80}$/,
};

function firstPresent(candidates) {
  for (const value of candidates) {
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return undefined;
}

function normalizeWebhookPointer(body) {
  const source = body && typeof body === 'object' ? body : {};
  const data = source.data && typeof source.data === 'object' ? source.data : {};
  const mailboxResourceId = firstPresent([
    source.mailboxResourceId,
    source.mailbox_resource_id,
    data.mailboxResourceId,
    data.mailbox_resource_id,
  ]);
  const folder = firstPresent([source.folder, data.folder]);
  const uidRaw = firstPresent([source.uid, data.uid]);
  const mailbox = firstPresent([source.mailbox, source.mailboxAddress, data.mailbox, data.mailboxAddress]);
  const eventType = firstPresent([source.event, source.event_type, source.type, data.event, data.event_type]);
  const uidText = uidRaw == null ? '' : String(uidRaw);
  if (!POINTER_RULES.mailbox_resource_id.test(String(mailboxResourceId || ''))) {
    return { ok: false, reason: 'pointer_incomplete' };
  }
  if (!POINTER_RULES.folder.test(String(folder || ''))) return { ok: false, reason: 'pointer_incomplete' };
  if (!/^\d{1,18}$/.test(uidText)) return { ok: false, reason: 'pointer_incomplete' };
  if (!POINTER_RULES.mailbox.test(String(mailbox || ''))) return { ok: false, reason: 'pointer_incomplete' };
  if (eventType != null && eventType !== '' && !POINTER_RULES.event_type.test(String(eventType))) {
    return { ok: false, reason: 'pointer_incomplete' };
  }
  return {
    ok: true,
    tenant_id: 'tvg',
    mailbox_resource_id: String(mailboxResourceId),
    folder: String(folder),
    uid: uidText,
    mailbox: String(mailbox).toLowerCase(),
    event_type: eventType ? String(eventType) : null,
  };
}

function settingValue(settings, key) {
  if (!settings || typeof settings !== 'object') return undefined;
  return settings[key];
}

function isEnabledFormSender(row, fromEmail) {
  if (!row || row.enabled === false) return false;
  return normalizeEmail(row.from_email) === fromEmail && fromEmail !== '';
}

function filterField(row, message) {
  const fromEmail = message.from_email || '';
  const local = fromEmail.split('@')[0] || '';
  const domain = fromEmail.split('@')[1] || '';
  const registrable = message.from_registrable || '';
  switch (row.kind) {
    case 'sender_deny':
    case 'sender_allow':
      return fromEmail;
    case 'domain_deny':
    case 'domain_allow':
    case 'vendor':
      return row.match_mode === 'domain' ? domain : registrable;
    case 'noreply_pattern':
      return local;
    case 'list_pattern':
      return `${message.list_id || ''} ${message.precedence_header || ''}`.toLowerCase();
    default:
      return '';
  }
}

function rowMatches(row, message) {
  if (!row || row.enabled === false) return false;
  const field = filterField(row, message);
  const pattern = String(row.pattern || '');
  const mode = row.match_mode || 'exact';
  if (mode === 'exact') return field.toLowerCase() === pattern.toLowerCase();
  if (mode === 'domain') {
    const domain = (message.from_email || '').split('@')[1] || '';
    const needle = pattern.toLowerCase();
    return domain.toLowerCase() === needle || (message.from_registrable || '') === needle;
  }
  if (mode === 'contains') return field.toLowerCase().includes(pattern.toLowerCase());
  if (mode === 'regex') {
    try {
      return new RegExp(pattern, 'i').test(field);
    } catch {
      return false;
    }
  }
  return false;
}

/**
 * Filter-kind field map used by this staging build.
 * Command Center item 1 is still OPEN; this is the implement default, not a signed lock.
 */
const FILTER_FIELD_MAP = Object.freeze({
  sender_deny: 'normalized From addr-spec',
  sender_allow: 'normalized From addr-spec',
  domain_deny: 'From domain (match_mode=domain compares domain or registrable domain)',
  domain_allow: 'From domain (same as domain_deny)',
  vendor: 'From domain',
  noreply_pattern: 'From local-part',
  list_pattern: 'List-Id header plus Precedence header',
  form_path: 'known_form_senders.from_email exact match on normalized From only',
});

function applyFilterLists(message, filterRows, { skipDeny = false } = {}) {
  const matches = (filterRows || []).filter((row) => rowMatches(row, message));
  const lessen = matches.find((row) => row.action === 'system_lessen' || row.kind === 'vendor');
  if (lessen && lessen.action === 'system_lessen') {
    return { outcome: 'system_lessen', reason: lessen.reason_code || 'vendor_lessen' };
  }
  if (!skipDeny) {
    const deny = matches.find((row) => row.action === 'deny');
    if (deny) return { outcome: 'filtered', reason: deny.reason_code || 'deny' };
  }
  return { outcome: 'none', reason: null };
}

function headerFilter(message) {
  if (message.is_dsn) return { outcome: 'filtered', reason: 'dsn' };
  const auto = String(message.auto_submitted || '').trim().toLowerCase();
  if (auto && auto !== 'no') return { outcome: 'filtered', reason: 'auto_submitted' };
  const precedence = String(message.precedence_header || '').trim().toLowerCase();
  if (['bulk', 'list', 'junk'].includes(precedence)) return { outcome: 'filtered', reason: 'precedence' };
  if (message.list_id) return { outcome: 'filtered', reason: 'list_id' };
  if (message.from_email && message.mailbox_email && message.from_email === message.mailbox_email) {
    return { outcome: 'filtered', reason: 'self_mail' };
  }
  return null;
}

function digits(phone) {
  return String(phone || '').replace(/\D/g, '');
}

function computeIdentity(message) {
  const body = normalizeBodyV1(message);
  const bodyHash = sha256Hex(body);
  const rawId = message.message_id == null ? '' : String(message.message_id).trim();
  const messageId = rawId ? rawId.replace(/^<|>$/g, '') : '';
  let fallbackHash = null;
  if (!messageId) {
    const canonical = [
      message.mailbox_email || '',
      message.from_email || '',
      message.to_email || '',
      normalizeSubject(message.subject),
      normalizeDateHeader(message.date_header),
      bodyHash,
    ].join('\u001f');
    fallbackHash = `v2:${sha256Hex(canonical)}`;
  }
  return {
    message_id: messageId || null,
    fallback_hash: fallbackHash,
    body_hash: bodyHash,
    body_normalized: body,
  };
}

function prepareMessage(message, suffixes) {
  const fromEmail = normalizeEmail(message.from_raw ?? message.from_email);
  const replyTo = normalizeEmail(message.reply_to_raw ?? message.reply_to_email);
  const toEmail = normalizeEmail(message.to_raw ?? message.to_email);
  const mailboxEmail = normalizeEmail(message.mailbox);
  const domain = fromEmail.split('@')[1] || '';
  return {
    ...message,
    from_email: fromEmail,
    reply_to_email: replyTo,
    to_email: toEmail,
    mailbox_email: mailboxEmail,
    from_registrable: registrableDomain(domain, suffixes),
    reply_to_registrable: registrableDomain((replyTo.split('@')[1] || ''), suffixes),
  };
}

function resolveRecipient(message, { isForm, authPass, formSender }) {
  if (isForm && !authPass) {
    return { hold_reason: 'form_auth_failure', resolved_recipient: null, recipient_resolution: null };
  }
  if (isForm && authPass && formSender && formSender.trust_reply_to !== false && message.reply_to_email) {
    const self = message.reply_to_email === message.mailbox_email;
    if (!self) {
      return {
        hold_reason: null,
        resolved_recipient: message.reply_to_email,
        recipient_resolution: 'reply_to_trusted_form',
      };
    }
  }
  if (isForm && authPass) {
    const formEmail = normalizeEmail(message.form_field_email);
    if (formEmail) {
      return { hold_reason: null, resolved_recipient: formEmail, recipient_resolution: 'form_field' };
    }
  }
  if (!isForm && message.reply_to_email && message.reply_to_registrable && message.from_registrable
    && message.reply_to_registrable !== message.from_registrable) {
    return { hold_reason: 'reply_to_domain_mismatch', resolved_recipient: null, recipient_resolution: null };
  }
  if (message.from_email && message.from_email !== message.mailbox_email) {
    return { hold_reason: null, resolved_recipient: message.from_email, recipient_resolution: 'from' };
  }
  return { hold_reason: 'ambiguous_recipient', resolved_recipient: null, recipient_resolution: null };
}

function matchCrm(message, contacts, leads, settings, resolvedRecipient) {
  const rows = Array.isArray(contacts) ? contacts : [];
  const nonTvg = rows.filter((row) => row.tenant_id && row.tenant_id !== 'tvg'
    && normalizeEmail(row.email) === resolvedRecipient);
  if (nonTvg.length) {
    return { hold_reason: 'cross_tenant_match', contact_id: null, lead_id: null };
  }
  const emailHits = rows.filter((row) => (row.tenant_id == null || row.tenant_id === 'tvg')
    && normalizeEmail(row.email) === resolvedRecipient);
  if (emailHits.length > 1) {
    return { hold_reason: 'ambiguous_contact', contact_id: null, lead_id: null };
  }
  const contact = emailHits[0] || null;
  const phone = digits(message.phone);
  if (phone.length >= 7) {
    const phoneHits = rows.filter((row) => digits(row.phone) === phone);
    const foreign = phoneHits.filter((row) => row.tenant_id && row.tenant_id !== 'tvg');
    if (foreign.length) return { hold_reason: 'cross_tenant_match', contact_id: null, lead_id: null };
    const tvgHits = phoneHits.filter((row) => !row.tenant_id || row.tenant_id === 'tvg');
    const conflict = tvgHits.filter((row) => normalizeEmail(row.email) !== resolvedRecipient);
    if (tvgHits.length > 1 || conflict.length) {
      return { hold_reason: 'phone_conflict', contact_id: null, lead_id: null };
    }
  }
  let leadId = null;
  if (contact) {
    const allow = settingValue(settings, 'open_lead_statuses');
    if (!Array.isArray(allow) || allow.length === 0) throw new Error('open_lead_statuses missing');
    const allowSet = new Set(allow.map((status) => String(status).toLowerCase()));
    const open = (leads || []).filter((lead) => lead.contact_id === contact.id
      && (!lead.tenant_id || lead.tenant_id === 'tvg')
      && allowSet.has(String(lead.status || '').toLowerCase()));
    if (open.length === 1) leadId = open[0].id;
  }
  return { hold_reason: null, contact_id: contact ? contact.id : null, lead_id: leadId };
}

function evaluateIntake({
  message,
  filterRows = [],
  formSenders = [],
  settings = {},
  contacts = [],
  leads = [],
  pslSuffixes = PSL_SUBSET,
}) {
  if (settingValue(settings, 'hold_on_form_auth_failure') !== true) {
    throw new Error('hold_on_form_auth_failure_must_be_true');
  }
  const prepared = prepareMessage(message, pslSuffixes);
  const identity = computeIdentity(prepared);
  const auth = parseAuthResults(prepared.authentication_results);
  const formSender = (formSenders || []).find((row) => isEnabledFormSender(row, prepared.from_email)) || null;
  const isForm = Boolean(formSender);
  const base = {
    ...identity,
    from_email: prepared.from_email,
    reply_to_email: prepared.reply_to_email,
    spf_pass: auth.spf_pass,
    dkim_pass: auth.dkim_pass,
    dmarc_pass: auth.dmarc_pass,
    is_form_sender: isForm,
    contact_id: null,
    lead_id: null,
    resolved_recipient: null,
    recipient_resolution: null,
    hold_reason: null,
    filter_reason: null,
  };

  if (isForm && !auth.all_pass) {
    return {
      ...base,
      event_status: 'held',
      queue_status: 'held',
      hold_reason: 'form_auth_failure',
    };
  }

  const filtered = isForm
    ? applyFilterLists(prepared, filterRows, { skipDeny: true })
    : (headerFilter(prepared) || applyFilterLists(prepared, filterRows));
  if (filtered.outcome === 'filtered' || filtered.outcome === 'system_lessen') {
    return {
      ...base,
      event_status: filtered.outcome,
      queue_status: 'done',
      filter_reason: filtered.reason,
    };
  }

  const recipient = resolveRecipient(prepared, { isForm, authPass: auth.all_pass, formSender });
  if (recipient.hold_reason) {
    return {
      ...base,
      event_status: 'held',
      queue_status: 'held',
      hold_reason: recipient.hold_reason,
    };
  }

  const crm = matchCrm(prepared, contacts, leads, settings, recipient.resolved_recipient);
  if (crm.hold_reason) {
    return {
      ...base,
      event_status: 'held',
      queue_status: 'held',
      hold_reason: crm.hold_reason,
      resolved_recipient: recipient.resolved_recipient,
      recipient_resolution: recipient.recipient_resolution,
    };
  }

  return {
    ...base,
    event_status: 'awaiting_pass2',
    queue_status: 'done',
    resolved_recipient: recipient.resolved_recipient,
    recipient_resolution: recipient.recipient_resolution,
    contact_id: crm.contact_id,
    lead_id: crm.lead_id,
  };
}

const ATTACHMENT_FORBIDDEN = new Set(['bytes', 'content', 'data', 'body', 'base64', 'payload', 'mime']);
const ATTACHMENT_ALLOWED = new Set(['filename', 'content_type', 'size_bytes', 'attachment_id']);

function assertAttachmentMetadataOnly(meta) {
  if (meta == null) return [];
  if (!Array.isArray(meta)) throw new Error('attachment_meta must be an array');
  return meta.map((item) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      throw new Error('attachment item must be an object');
    }
    const clean = {};
    for (const key of Object.keys(item)) {
      if (ATTACHMENT_FORBIDDEN.has(key)) throw new Error('attachment bytes are outside Pass 1');
      if (!ATTACHMENT_ALLOWED.has(key)) throw new Error('attachment field is not metadata');
      clean[key] = item[key];
    }
    return {
      filename: clean.filename == null ? null : String(clean.filename).slice(0, 200),
      content_type: clean.content_type == null ? null : String(clean.content_type).slice(0, 120),
      size_bytes: Number.isFinite(Number(clean.size_bytes)) ? Number(clean.size_bytes) : null,
      attachment_id: clean.attachment_id == null ? null : String(clean.attachment_id).slice(0, 200),
    };
  });
}

function captureThreadMetadata(message) {
  const clip = (value) => String(value || '').slice(0, 2000);
  return {
    in_reply_to: clip(message?.in_reply_to || message?.inReplyTo || ''),
    references_header: clip(message?.references || message?.references_header || ''),
  };
}

function buildOutcomeSql(input) {
  const queueId = requireUuid(input.queue_id);
  if (!EVENT_STATUSES.has(input.event_status)) throw new Error('bad event status');
  if (!QUEUE_STATUSES.has(input.queue_status)) throw new Error('bad queue status');
  if (input.hold_reason != null && !HOLD_REASONS.has(input.hold_reason)) throw new Error('bad hold reason');
  if (!input.message_id && !input.fallback_hash) throw new Error('identity required');
  const contactSql = input.contact_id == null ? 'NULL' : `${quoteLiteral(requireUuid(input.contact_id))}::uuid`;
  const leadSql = input.lead_id == null ? 'NULL' : `${quoteLiteral(requireUuid(input.lead_id))}::uuid`;
  const conflict = input.message_id
    ? 'ON CONFLICT (tenant_id, mailbox, message_id) WHERE message_id IS NOT NULL DO NOTHING'
    : 'ON CONFLICT (tenant_id, mailbox, fallback_hash) WHERE fallback_hash IS NOT NULL DO NOTHING';
  const identityWhere = input.message_id
    ? `message_id = ${quoteLiteral(input.message_id)}`
    : `fallback_hash = ${quoteLiteral(input.fallback_hash)}`;
  const excerpt = String(input.body_excerpt || '').slice(0, 500);
  const thread = captureThreadMetadata(input);
  const attachments = assertAttachmentMetadataOnly(input.attachment_meta);
  const fetchParts = [];
  if (input.fetch_base_url != null && input.fetch_base_url !== '') {
    fetchParts.push(`'fetch_base_url', ${quoteLiteral(String(input.fetch_base_url).slice(0, 300))}::text`);
  }
  if (input.fetch_mode != null && input.fetch_mode !== '') {
    fetchParts.push(`'fetch_mode', ${quoteLiteral(String(input.fetch_mode).slice(0, 40))}::text`);
  }
  const pointerMerge = fetchParts.length
    ? `hostinger_pointers = COALESCE(q.hostinger_pointers, '{}'::jsonb) || jsonb_build_object(${fetchParts.join(', ')}),`
    : '';
  const inReply = thread.in_reply_to ? quoteLiteral(thread.in_reply_to) : 'NULL';
  const referencesHeader = thread.references_header ? quoteLiteral(thread.references_header) : 'NULL';
  return `
WITH inserted AS (
  INSERT INTO email_automation.email_events (
    tenant_id, mailbox, mailbox_resource_id, message_id, fallback_hash, folder, uid,
    status, filter_reason, hold_reason, from_email, reply_to_email, subject,
    message_date_header, body_hash, resolved_recipient, recipient_resolution,
    authentication_results, spf_pass, dkim_pass, dmarc_pass, body_text_excerpt,
    in_reply_to, references_header, has_attachments, attachment_meta,
    contact_id, lead_id, fetched_at
  ) VALUES (
    'tvg',
    ${quoteLiteral(input.mailbox)},
    ${quoteLiteral(input.mailbox_resource_id)},
    ${input.message_id ? quoteLiteral(input.message_id) : 'NULL'},
    ${input.fallback_hash ? quoteLiteral(input.fallback_hash) : 'NULL'},
    ${quoteLiteral(input.folder)},
    ${quoteLiteral(input.uid)}::bigint,
    ${quoteLiteral(input.event_status)}::email_automation.email_event_status,
    ${input.filter_reason ? quoteLiteral(input.filter_reason) : 'NULL'},
    ${input.hold_reason ? quoteLiteral(input.hold_reason) : 'NULL'},
    ${input.from_email ? quoteLiteral(input.from_email) : 'NULL'},
    ${input.reply_to_email ? quoteLiteral(input.reply_to_email) : 'NULL'},
    ${input.subject ? quoteLiteral(input.subject) : 'NULL'},
    ${input.date_header ? quoteLiteral(input.date_header) : 'NULL'},
    ${quoteLiteral(input.body_hash)},
    ${input.resolved_recipient ? quoteLiteral(input.resolved_recipient) : 'NULL'},
    ${input.recipient_resolution ? quoteLiteral(input.recipient_resolution) : 'NULL'},
    ${input.authentication_results ? quoteLiteral(input.authentication_results) : 'NULL'},
    ${input.spf_pass ? 'TRUE' : 'FALSE'},
    ${input.dkim_pass ? 'TRUE' : 'FALSE'},
    ${input.dmarc_pass ? 'TRUE' : 'FALSE'},
    ${excerpt ? quoteLiteral(excerpt) : 'NULL'},
    ${inReply},
    ${referencesHeader},
    ${attachments.length > 0 ? 'TRUE' : 'FALSE'},
    ${quoteLiteral(JSON.stringify(attachments))}::jsonb,
    ${contactSql},
    ${leadSql},
    now()
  )
  ${conflict}
  RETURNING id
),
existing AS (
  SELECT id FROM email_automation.email_events
  WHERE tenant_id = 'tvg' AND mailbox = ${quoteLiteral(input.mailbox)} AND ${identityWhere}
),
chosen AS (
  SELECT id, FALSE AS was_existing FROM inserted
  UNION ALL
  SELECT id, TRUE AS was_existing FROM existing
  WHERE NOT EXISTS (SELECT 1 FROM inserted)
  LIMIT 1
)
UPDATE email_automation.intake_queue q
SET ${pointerMerge}
    email_event_id = chosen.id,
    message_id = ${input.message_id ? quoteLiteral(input.message_id) : 'NULL'},
    fallback_hash = ${input.fallback_hash ? quoteLiteral(input.fallback_hash) : 'NULL'},
    status = CASE
      WHEN chosen.was_existing THEN 'duplicate'::email_automation.intake_queue_status
      ELSE ${quoteLiteral(input.queue_status)}::email_automation.intake_queue_status
    END,
    hold_reason = ${input.hold_reason ? quoteLiteral(input.hold_reason) : 'NULL'}
FROM chosen
WHERE q.id = ${quoteLiteral(queueId)}::uuid
  AND q.tenant_id = 'tvg'
RETURNING q.id, q.status, q.email_event_id, chosen.was_existing,
  (SELECT e.created_at FROM email_automation.email_events e WHERE e.id = q.email_event_id) AS event_created_at;
`.trim();
}

function planFastAck(body) {
  const pointer = normalizeWebhookPointer(body);
  if (!pointer.ok) {
    return {
      http_status: 400,
      response_body: { ok: false, error: pointer.reason },
      sql: null,
      sample_sql: null,
    };
  }
  const killSwitchSql = `(
  SELECT COALESCE((
    SELECT value_json = 'true'::jsonb
    FROM email_automation.automation_settings
    WHERE tenant_id = 'tvg' AND key = 'intake_processing_enabled'
  ), true)
)`;
  return {
    http_status: 200,
    response_body: { ok: true },
    sample_sql: null,
    sql: `
INSERT INTO email_automation.intake_queue (
  tenant_id, mailbox, mailbox_resource_id, folder, uid, event_type, status, hostinger_pointers
) VALUES (
  'tvg',
  ${quoteLiteral(pointer.mailbox)},
  ${quoteLiteral(pointer.mailbox_resource_id)},
  ${quoteLiteral(pointer.folder)},
  ${quoteLiteral(pointer.uid)}::bigint,
  ${pointer.event_type ? quoteLiteral(pointer.event_type) : 'NULL'},
  CASE WHEN ${killSwitchSql} THEN 'pending'::email_automation.intake_queue_status
       ELSE 'deferred_kill_switch'::email_automation.intake_queue_status END,
  ${quoteLiteral(JSON.stringify({
    mailbox_resource_id: pointer.mailbox_resource_id,
    folder: pointer.folder,
    uid: pointer.uid,
    source: 'fast_ack_normalized',
  }))}::jsonb
)
ON CONFLICT (tenant_id, mailbox_resource_id, folder, uid) DO NOTHING
RETURNING id, status;`.trim(),
  };
}

function buildFastPathInsertSql(pointer, { killSwitchEnabled }) {
  if (!pointer?.ok) throw new Error('pointer required');
  const status = killSwitchEnabled ? 'pending' : 'deferred_kill_switch';
  return `
INSERT INTO email_automation.intake_queue (
  tenant_id, mailbox, mailbox_resource_id, folder, uid, event_type, status, hostinger_pointers
) VALUES (
  'tvg',
  ${quoteLiteral(pointer.mailbox)},
  ${quoteLiteral(pointer.mailbox_resource_id)},
  ${quoteLiteral(pointer.folder)},
  ${quoteLiteral(pointer.uid)}::bigint,
  ${pointer.event_type ? quoteLiteral(pointer.event_type) : 'NULL'},
  ${quoteLiteral(status)}::email_automation.intake_queue_status,
  ${quoteLiteral(JSON.stringify({
    mailbox_resource_id: pointer.mailbox_resource_id,
    folder: pointer.folder,
    uid: pointer.uid,
    source: 'fast_ack_normalized',
  }))}::jsonb
)
ON CONFLICT (tenant_id, mailbox_resource_id, folder, uid) DO NOTHING
RETURNING id, status;
`.trim();
}

function buildGapFillSql(messages) {
  if (!Array.isArray(messages) || messages.length === 0) throw new Error('synthetic inbox required');
  const values = messages.map((message) => {
    const pointer = normalizeWebhookPointer(message);
    if (!pointer.ok) throw new Error('gap-fill pointer incomplete');
    return `(${quoteLiteral(pointer.mailbox)}, ${quoteLiteral(pointer.mailbox_resource_id)}, ${quoteLiteral(pointer.folder)}, ${quoteLiteral(pointer.uid)}::bigint)`;
  }).join(',\n');
  return `
INSERT INTO email_automation.intake_queue (
  tenant_id, mailbox, mailbox_resource_id, folder, uid, status, hostinger_pointers
)
SELECT 'tvg', v.mailbox, v.mailbox_resource_id, v.folder, v.uid,
       'pending'::email_automation.intake_queue_status,
       jsonb_build_object('source', 'synthetic_inbox_gap_fill', 'folder', v.folder, 'uid', v.uid)
FROM (VALUES
${values}
) AS v(mailbox, mailbox_resource_id, folder, uid)
ON CONFLICT (tenant_id, mailbox_resource_id, folder, uid) DO NOTHING
RETURNING id;
`.trim();
}

function assertStagingTarget({ projectRef, databaseUrl }) {
